int main(){
    int t; cin >> t;
    while (t--){
        int n; cin >> n;

        vector <int> a(n + 1);
        for (int i = 1; i <= n; i++){
            cin >> a[i];
        }

        vector <long long> dp(n + 1, 1e18);
        dp[n] = 0;

        for (int i = n - 1; i >= 0; i--){
            int p = i + 1;
            for (int j = i + 1; j <= n; j++) if (a[j] < a[p]){
                p = j;
            }

            for (int j = p; j <= n; j++){
